// Detect the trigger from its payload (not from $execution.mode): the schedule trigger sends a timestamp and
// 'Day of week'/'Readable date', a webhook sends a body with requestKind, the manual trigger sends an empty object.
const raw = ($input.first() && $input.first().json) || {};
const fromSchedule = Boolean(raw.timestamp && (raw['Day of week'] !== undefined || raw['Readable date'] !== undefined));
const fromWebhook = raw.requestKind !== undefined;
const triggerKind = fromSchedule ? 'SCHEDULED' : (fromWebhook ? 'WEBHOOK' : 'MANUAL');

const nowUtc = new Date();
const msk = new Date(nowUtc.getTime() + 3 * 3600000);
const dateMsk = msk.toISOString().slice(0, 10);

const q = v => (v === null || v === undefined || v === '') ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'";
const runId = 'STOCK-TURNOVER-' + $workflow.id + '-' + $execution.id + '-' + dateMsk;
const insertRunSql = 'INSERT INTO ops.collector_run (run_id, run_date, trigger_type, status, started_at, generated_by) VALUES ('
  + [q(runId), 'date ' + q(dateMsk), q('STOCK_TURNOVER_COLLECT'), q('RUNNING'), q(nowUtc.toISOString()) + '::timestamptz', q('stock_and_cluster_orders_daily')].join(',')
  + ') ON CONFLICT (run_id) DO UPDATE SET status=' + q('RUNNING') + ', started_at=now(), trigger_type=EXCLUDED.trigger_type'
  + ' RETURNING run_id, run_date, trigger_type';

return [{ json: {
  runId: runId,
  businessDate: dateMsk,
  capturedAt: nowUtc.toISOString(),
  triggerKind: triggerKind,
  requestKind: fromWebhook ? String(raw.requestKind) : null,
  startedAt: nowUtc.toISOString(),
  insertRunSql: insertRunSql
} }];

const ctx = $('Init Run').first().json;
const nums = $input.all().map(i => Number(i.json.sku)).filter(n => Number.isSafeInteger(n) && n > 0);
const skus = Array.from(new Set(nums)).sort((a, b) => a - b);
if (skus.length === 0) {
  throw new Error('STOCK_NO_SKU_UNIVERSE: raw.sku returned no numeric SKU');
}
if (skus.length > 1000) {
  throw new Error('STOCK_TURNOVER_SKU_UNIVERSE_TOO_BIG: ' + skus.length + ' SKUs exceed the request limit of 1000; pagination is needed instead of silent truncation');
}
const skusStr = skus.map(String);
return [{ json: Object.assign({}, ctx, {
  skus: skus,
  skusStr: skusStr,
  skuCount: skus.length,
  turnoverBody: {
  limit: 1000,
  offset: 0,
  sku: skusStr
},
  sowBody: {
  limit: 1000,
  offset: 0,
  warehouse_type: 'ALL'
},
  fboBody: {
  skus: skusStr,
  limit: 1000
}
}) }];

const EXTRACT_BODY = function (body) {
  if (!body || typeof body !== 'object') return null;
  if (Array.isArray(body.items)) return body.items;
  if (Array.isArray(body.result)) return body.result;
  if (body.result && Array.isArray(body.result.items)) return body.result.items;
  if (body.result && Array.isArray(body.result.rows)) return body.result.rows;
  if (Array.isArray(body.rows)) return body.rows;
  return null;
};

const crypto = require('crypto');
const sha256 = s => crypto.createHash('sha256').update(s, 'utf8').digest('hex');
const ctx = $('Collect Context').first().json;
const METHOD = 'turnover_stocks';
const ENDPOINT = '/v1/analytics/turnover/stocks';
const TABLE = 'landing.stock_turnover';
const LIMIT = 1000;

const out = {
  method: METHOD, endpoint: ENDPOINT, table: TABLE,
  http_status: 0, rows_parsed: 0, rows_landed: 0,
  error: null, response_sha256: '', raw_bytes: 0, body_keys: '', insert_sql: ''
};

const it = ($input.first() && $input.first().json) || {};
const status = Number(it.statusCode !== undefined ? it.statusCode : (it.status !== undefined ? it.status : 0));
out.http_status = status;

let text = null;
try {
  const buf = await this.helpers.getBinaryDataBuffer(0, 'rawTurnover');
  if (buf) { text = buf.toString('utf8'); out.raw_bytes = buf.length; }
} catch (e) { text = null; }

if (text === null) {
  out.error = 'NO_RESPONSE_BODY: no response body; statusCode=' + status + '; json=' + JSON.stringify(it).slice(0, 800);
} else {
  out.response_sha256 = sha256(text);
  let body = null;
  try { body = JSON.parse(text); } catch (e) { out.error = 'RESPONSE_NOT_JSON: ' + String(e.message) + '; body=' + text.slice(0, 800); }
  if (body !== null && out.error === null) {
    out.body_keys = Object.keys(body || {}).join(',');
    if (status !== 200) {
      out.error = 'HTTP_' + status + ': ' + text.slice(0, 1500);
    } else {
      const rows = EXTRACT_BODY(body);
      if (!Array.isArray(rows) || rows.length === 0) {
        out.error = 'EMPTY_RESULT: response keys=[' + out.body_keys + ']; body=' + text.slice(0, 1500);
      } else {
        const cursorLeft = typeof body.cursor === 'string' && body.cursor.length > 0 && rows.length >= LIMIT;
        const totalLeft = Number.isFinite(Number(body.total)) && Number(body.total) > rows.length;
        if (cursorLeft || totalLeft) {
          out.error = 'PAGES_REMAIN: got ' + rows.length + ' rows, cursor=' + JSON.stringify(body.cursor) + ', total=' + JSON.stringify(body.total);
        } else {
          const arr = [];
          for (const r of rows) {
            const skuRaw = (r.sku !== undefined && r.sku !== null) ? r.sku : r.product_id;
            const skuNum = Number(skuRaw);
            if (!Number.isSafeInteger(skuNum) || skuNum <= 0) {
              out.error = 'BAD_SKU_IN_RESPONSE: ' + JSON.stringify(r).slice(0, 400);
              break;
            }
            arr.push({
              sku: skuNum,
              offer_id: String(r.offer_id !== undefined ? r.offer_id : (r.item_code !== undefined ? r.item_code : '')),
              warehouse_name: String(r.warehouse_name !== undefined ? r.warehouse_name : ''),
              row_sha256: sha256(JSON.stringify(r)),
              raw: r
            });
          }
          if (out.error === null && arr.length === 0) {
            out.error = 'NO_MAPPABLE_ROWS: rows in response ' + rows.length;
          }
          if (out.error === null) {
            out.rows_parsed = arr.length;
            const literal = '$strows$' + JSON.stringify(arr).split('$strows$').join('_strows_') + '$strows$';
            const selectList = "date '" + ctx.businessDate + "', s.sku, s.offer_id, s.warehouse_name, (s.raw->>'turnover')::numeric, (s.raw->>'current_stock')::numeric, (s.raw->>'ads')::numeric, '" + ENDPOINT + "', '" + ctx.runId + "', timestamptz '" + ctx.capturedAt
  + "', 1 + coalesce((SELECT max(r.revision) FROM " + TABLE
  + " r WHERE r.business_date = date '" + ctx.businessDate
  + "' AND r.sku = s.sku AND r.warehouse_name = s.warehouse_name), 0), "
  + out.http_status + ", '" + out.response_sha256 + "', s.row_sha256, s.raw";
            out.insert_sql =
              'WITH payload AS (SELECT ' + literal + '::jsonb AS arr), '
              + 'src AS (SELECT (e->>\'sku\')::bigint AS sku, coalesce(e->>\'offer_id\',\'\') AS offer_id, '
              + 'coalesce(e->>\'warehouse_name\',\'\') AS warehouse_name, e->>\'row_sha256\' AS row_sha256, e->\'raw\' AS raw '
              + 'FROM payload, jsonb_array_elements(payload.arr) AS e), '
              + 'ins AS (INSERT INTO ' + TABLE + ' (business_date, sku, offer_id, warehouse_name, turnover_days, current_stock, daily_sales, source_endpoint, run_id, captured_at, revision, http_status, response_sha256, row_sha256, raw) '
              + 'SELECT ' + selectList + ' FROM src s RETURNING 1) '
              + 'SELECT count(*) AS inserted_rows FROM ins';
          }
        }
      }
    }
  }
}
if (out.error !== null || !out.insert_sql) {
  out.rows_parsed = 0;
  out.insert_sql = 'SELECT 0 AS inserted_rows';
}
return [{ json: out }];

const EXTRACT_BODY = function (body) {
  if (!body || typeof body !== 'object') return null;
  if (body.result && Array.isArray(body.result.rows)) return body.result.rows;
  if (Array.isArray(body.result)) return body.result;
