const crypto = require('crypto');
const sha256 = s => crypto.createHash('sha256').update(s, 'utf8').digest('hex');
const ctx = $('Collect Context').first().json;
const METHOD = 'fbo_stocks_by_warehouse';
const ENDPOINT = '/v1/product/info/stocks-by-warehouse/fbo';
const TABLE = 'landing.fbo_stock_by_warehouse';
const LIMIT = 1000;

const out = {
  method: METHOD, endpoint: ENDPOINT, table: TABLE,
  http_status: 0, rows_parsed: 0, rows_landed: 0,
  error: null, response_sha256: '', raw_bytes: 0, body_keys: '', insert_sql: ''
};


const items = $input.all();
const needsMore = function (pageBody, pageRows) {
  if (!pageBody || !Array.isArray(pageRows)) return false;
  if (pageBody.has_next === true) return true;
  if (pageBody.has_next === false) return false;
  return typeof pageBody.cursor === 'string' && pageBody.cursor.length > 0 && pageRows.length >= LIMIT;
};
const MAX_PAGES = 20;
if (!items.length) {
  out.error = 'NO_RESPONSE_BODY: no pages';
} else {
  const rows = [];
  const pageTexts = [];
  let pages = 0;
  let lastBody = null;
  let lastRows = [];
  for (let i = 0; i < items.length; i++) {
    if (pages >= MAX_PAGES) {
      out.error = 'PAGES_REMAIN: pages=' + pages + ' extra_items=' + (items.length - i);
      break;
    }
    const item = (items[i] && items[i].json) || {};
    const statusN = Number(item.statusCode !== undefined ? item.statusCode : 0);
    if (i === 0) out.http_status = statusN;
    let parsed = null;
    if (item.body !== undefined && item.body !== null) parsed = item.body;
    else if (item.products || item.stocks || item.result) parsed = item;
    if (typeof parsed === 'string') {
      try { parsed = JSON.parse(parsed); } catch (e2) {
        out.error = 'RESPONSE_NOT_JSON: page=' + (i + 1);
        break;
      }
    }
    if (!parsed || typeof parsed !== 'object') {
      out.error = 'NO_RESPONSE_BODY: page=' + (i + 1) + ' status=' + statusN;
      break;
    }
    const pageText = JSON.stringify(parsed);
    pageTexts.push(pageText);
    if (i === 0) out.body_keys = Object.keys(parsed).join(',');
    if (statusN !== 200) {
      out.error = 'HTTP_' + statusN + ': page=' + (i + 1);
      break;
    }
    const pageRows = EXTRACT_BODY(parsed);
    if (!Array.isArray(pageRows) || pageRows.length === 0) {
      out.error = 'EMPTY_PAGE: page=' + (i + 1) + ' keys=' + Object.keys(parsed).join(',');
      break;
    }
    rows.push.apply(rows, pageRows);
    lastBody = parsed;
    lastRows = pageRows;
    pages += 1;
  }
  if (out.error === null && needsMore(lastBody, lastRows)) {
    out.error = 'PAGES_REMAIN: pages=' + pages + ' last_rows=' + lastRows.length + ' has_next=' + JSON.stringify(lastBody && lastBody.has_next);
  }
  if (out.error === null) {
    const deduped = [];
    const seen = new Set();
    for (let j = rows.length - 1; j >= 0; j--) {
      const row = rows[j];
      const skuKey = String(row.sku !== undefined && row.sku !== null ? row.sku : row.product_id);
      const whKey = String((row.warehouse_name !== undefined && row.warehouse_name !== null && String(row.warehouse_name) !== '') ? row.warehouse_name : (row.warehouse_id !== undefined && row.warehouse_id !== null ? row.warehouse_id : ''));
      const dedupeKey = skuKey + '|' + whKey;
      if (seen.has(dedupeKey)) continue;
      seen.add(dedupeKey);
      deduped.push(row);
    }
    deduped.reverse();
    rows.length = 0;
    rows.push.apply(rows, deduped);
    out.response_sha256 = sha256(pageTexts.join('|'));
    out.raw_bytes = pageTexts.reduce(function (sum, part) { return sum + part.length; }, 0);
    out.body_keys = out.body_keys + ';pages=' + pages + ';rows=' + rows.length;
  }
  if (out.error !== null) {
  } else {
          const arr = [];
          for (const r of rows) {
            const skuRaw = (r.sku !== undefined && r.sku !== null) ? r.sku : r.product_id;
