  + "', 1 + coalesce((SELECT max(r.revision) FROM " + TABLE
  + " r WHERE r.business_date = date '" + ctx.businessDate
  + "' AND r.sku = s.sku AND r.warehouse_name = s.warehouse_name), 0), "
  + out.http_status + ", '" + out.response_sha256 + "', s.row_sha256, s.raw";
            out.insert_sql =
              'WITH payload AS (SELECT ' + literal + '::jsonb AS arr), '
              + 'src AS (SELECT (e->>\'sku\')::bigint AS sku, coalesce(e->>\'offer_id\',\'\') AS offer_id, '
              + 'coalesce(e->>\'warehouse_name\',\'\') AS warehouse_name, e->>\'row_sha256\' AS row_sha256, e->\'raw\' AS raw '
              + 'FROM payload, jsonb_array_elements(payload.arr) AS e), '
              + 'ins AS (INSERT INTO ' + TABLE + ' (business_date, sku, offer_id, warehouse_name, item_name, free_to_sell_amount, promised_amount, reserved_amount, source_endpoint, run_id, captured_at, revision, http_status, response_sha256, row_sha256, raw) '
              + 'SELECT ' + selectList + ' FROM src s RETURNING 1) '
              + 'SELECT count(*) AS inserted_rows FROM ins';
          }
  }
}
if (out.error !== null || !out.insert_sql) {
  out.rows_parsed = 0;
  out.insert_sql = 'SELECT 0 AS inserted_rows';
}
return [{ json: out }];

// Compare rows parsed from each response with rows that actually landed (read back by run_id).
const ctx = $('Collect Context').first().json;
const cnt = ($input.first() && $input.first().json) || {};
const read = name => { try { const o = $(name).first(); return o ? o.json : null; } catch (e) { return null; } };
const q = v => (v === null || v === undefined || v === '') ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'";
const qi = v => { const n = Number(v); return Number.isFinite(n) ? String(Math.round(n)) : 'NULL'; };
const jd = v => '$stx$' + String(v).split('$stx$').join('_stx_') + '$stx$';

const plan = [
  ['Parse Turnover', 'turnover_landed'],
  ['Parse Stock On Warehouses', 'sow_landed'],
  ['Parse FBO Stocks', 'fbo_landed']
];
const methods = [];
let itemsWritten = 0;
for (const p of plan) {
  const r = read(p[0]);
  if (!r) { throw new Error('BRANCH_RECORD_MISSING: node ' + p[0] + ' returned no method record'); }
  const landed = Number(cnt[p[1]]);
  if (!Number.isFinite(landed)) { throw new Error('READBACK_COUNT_NOT_NUMERIC: ' + p[1] + '=' + JSON.stringify(cnt[p[1]])); }
  if (!r.error && landed !== Number(r.rows_parsed)) {
    throw new Error('LANDED_COUNT_MISMATCH: ' + r.method + ' parsed ' + r.rows_parsed + ', landed ' + landed);
  }
  if (!r.error && landed <= 0) {
    throw new Error('NO_ROWS_LANDED: ' + r.method + ' landed no rows in ' + r.table);
  }
  r.rows_landed = landed;
  itemsWritten += landed;
  methods.push(r);
}
const failed = methods.filter(m => m.error || m.rows_landed <= 0);
const overall = failed.length === 0 ? 'COMPLETED' : 'FAILED';

const detail = {
  event_type: 'STOCK_TURNOVER_COLLECT',
  trigger_kind: ctx.triggerKind,
  request_kind: ctx.requestKind,
  business_date: ctx.businessDate,
  sku_universe_count: ctx.skuCount,
  target_schema: 'landing',
  items_written: itemsWritten,
  methods_ok: methods.length - failed.length,
  methods_failed: failed.length,
  methods: methods.map(m => ({
    method: m.method,
    endpoint: m.endpoint,
    table: m.table,
    http_status: m.http_status,
    rows_parsed: m.rows_parsed,
    rows_landed: m.rows_landed,
    response_sha256: m.response_sha256,
    raw_bytes: m.raw_bytes,
    body_keys: m.body_keys,
    error: m.error ? String(m.error).slice(0, 1200) : null
  })),
  note: failed.length === 0
    ? 'all three methods returned data and the rows landed'
    : 'some methods returned no data; see the error of each method in methods'
};

const errText = failed.length === 0 ? null
  : failed.map(m => m.method + ': ' + String(m.error || 'no rows landed')).join(' | ').slice(0, 900);

const finishRunSql = 'UPDATE ops.collector_run SET status=' + q(overall)
  + ', finished_at=now(), items_written=' + qi(itemsWritten)
  + ', error=' + q(errText)
  + ', detail=' + jd(JSON.stringify(detail)) + '::jsonb'
  + ', generated_by=' + q('stock_and_cluster_orders_daily')
  + ' WHERE run_id=' + q(ctx.runId)
  + ' RETURNING run_id, status, items_written';

return [{ json: {
  runId: ctx.runId, overall: overall, itemsWritten: itemsWritten,
  expectedDetail: detail, finishRunSql: finishRunSql
} }];

// Error branch: a FAILED run record is written in every case (a failed run is still recorded).
const read = name => { try { const o = $(name).first(); return o ? o.json : null; } catch (e) { return null; } };
const ctx = read('Init Run') || {};
const j = ($input.first() && $input.first().json) || {};
const err = (j.error && (j.error.message || j.error.description))
  || (j.executionError && (j.executionError.description || j.executionError.message))
  || j.message || JSON.stringify(j).slice(0, 600);
const errText = String(err).slice(0, 900);
const failedNode = (j.node && j.node.name) || null;
const q = v => (v === null || v === undefined || v === '') ? 'NULL' : "'" + String(v).replace(/'/g, "''") + "'";
