return [{ json: { runId: ctx.runId, overall: 'FAILED', itemsWritten: 0, errorText: errText, finishRunSql: finishRunSql } }];

// Read the run record back and verify it. Then a fail-closed gate: if the run is not COMPLETED,
// the execution must end with an error, never with a green status.
const row = ($input.first() && $input.first().json) || null;
const read = name => { try { const o = $(name).first(); return o ? o.json : null; } catch (e) { return null; } };
const expected = read('Verify Landed Rows') || read('Fail Run') || null;

if (!row || !row.run_id) {
  throw new Error('RECEIPT_READBACK_EMPTY: run record not found in ops.collector_run, run_id=' + (expected ? expected.runId : 'unknown'));
}
if (!expected) {
  throw new Error('RECEIPT_NO_EXPECTATION: nothing to compare the run record with, run_id=' + row.run_id);
}
if (row.run_id !== expected.runId) {
  throw new Error('RECEIPT_RUN_ID_MISMATCH: db=' + row.run_id + ' expected=' + expected.runId);
}
