  throw new Error('RECEIPT_COLUMN_ITEMS_MISMATCH: column items_written=' + row.items_written + ' expected=' + expected.itemsWritten);
}
if (expected.expectedDetail) {
  const e = expected.expectedDetail;
  if (detail.event_type !== e.event_type || detail.business_date !== e.business_date) {
    throw new Error('RECEIPT_DETAIL_MISMATCH: event_type or business_date differs from the expected value');
  }
  if (Number(detail.items_written) !== Number(e.items_written)) {
    throw new Error('RECEIPT_ITEMS_MISMATCH: db=' + detail.items_written + ' expected=' + e.items_written);
  }
  if (Array.isArray(detail.methods) && Array.isArray(e.methods) && detail.methods.length !== e.methods.length) {
    throw new Error('RECEIPT_METHODS_MISMATCH: db=' + detail.methods.length + ' expected=' + e.methods.length);
  }
}
if (String(row.status) !== 'COMPLETED') {
  throw new Error('STOCK_RUN_FAILED (fail-closed): run_id=' + row.run_id + '; ' + String(row.error || JSON.stringify(detail)).slice(0, 900));
}
const m = Array.isArray(detail.methods) ? detail.methods : [];
return [{ json: {
  run_id: row.run_id,
  status: row.status,
  business_date: detail.business_date,
  trigger_kind: detail.trigger_kind,
  items_written: Number(detail.items_written),
  methods: m.map(x => ({ method: x.method, endpoint: x.endpoint, http_status: x.http_status, rows_landed: x.rows_landed, response_sha256: x.response_sha256, error: x.error })),
  receipt_verified: true
} }];

// CL: build 4 day-requests (D-4..D-1, MSK days; filter = created_at)
const DAYS = 4;
const nowMsk = new Date(Date.now() + 3*3600*1000);
const todayMsk = new Date(Date.UTC(nowMsk.getUTCFullYear(), nowMsk.getUTCMonth(), nowMsk.getUTCDate()));
const out = [];
for (let i = DAYS; i >= 1; i--) {
  const d = new Date(todayMsk.getTime() - i*86400000);
  const since = new Date(d.getTime() - 3*3600*1000), to = new Date(since.getTime() + 86400000);
  out.push({json:{day: d.toISOString().slice(0,10), body:{cursor:'', filter:{since: since.toISOString().replace('.000',''), to: to.toISOString().replace('.000','')}, limit:100, sort_dir:'asc', translit:false, with:{analytics_data:true, financial_data:true, legal_info:false}}}});
}
return out;

// CL: flatten postings -> rows for raw.fbo_posting_line_obs
