  if (buf) { try { b = JSON.parse(buf.toString('utf8')); } catch (e) { b = {}; } }
  if (sc !== '200' || !Array.isArray(b.postings)) { flags.push(day+':HTTP_'+sc+':'+(buf?buf.length:0)+'B'); continue; }
